package com.oea.games.arena

import com.oea.engine.OeaEngine
import com.oea.engine.graphics.CharacterAsset
import com.oea.engine.graphics.CharacterAssetLoader
import org.json.JSONObject

/**
 * The identified Send Off soldiers bundled with the game. The manifest is
 * generated by `tools/tripo/concept_to_oeac.py --all`, so the art pipeline and
 * the runtime cannot drift apart. Assets are loaded lazily and shared.
 */
internal class CharacterCatalog {
    class Entry(
        val id: String,
        val name: String,
        val role: String,
        val assetPath: String,
        val textureDir: String,
        val color: Int,
    )

    private val entries = ArrayList<Entry>()
    private val cache = HashMap<String, CharacterAsset>()

    fun load() {
        if (entries.isNotEmpty()) return
        val text = OeaEngine.context.assets.open("characters/manifest.json").bufferedReader().use { it.readText() }
        val array = JSONObject(text).optJSONArray("characters") ?: return
        for (i in 0 until array.length()) {
            val o = array.optJSONObject(i) ?: continue
            val id = o.optString("id", "")
            if (id.isEmpty()) continue
            entries += Entry(
                id = id,
                name = o.optString("name", id),
                role = o.optString("role", ""),
                assetPath = o.optString("asset", "characters/$id.oeac"),
                textureDir = o.optString("textures", "characters/$id"),
                color = o.optInt("color", -1),
            )
        }
    }

    val all: List<Entry> get() = entries

    fun hero(): Entry? = entries.firstOrNull { it.id == "hero" }

    /** Deterministic bot identity: same player id always gets the same soldier. */
    fun bot(seed: Int): Entry? {
        val bots = entries.filter { it.id != "hero" }
        return bots.getOrNull(Math.floorMod(seed, bots.size.coerceAtLeast(1)))
    }

    /** Loaded art for one id, or null when the bundled asset is missing/corrupt. */
    fun asset(id: String): CharacterAsset? = runCatching {
        cache.getOrPut(id) {
            val entry = entries.firstOrNull { it.id == id } ?: error("unknown character $id")
            CharacterAssetLoader.fromAssets(entry.assetPath, entry.textureDir)
        }
    }.getOrNull()
}
